import sqlite3
from contextlib import closing
import stripe
stripe.api_key = 'sk_live_clinic_placeholder'

def _load_booking(cur, appointment_id):
    cur.execute('SELECT id, status, deposit_charge_id, deposit_cents FROM appointments WHERE id = ?', (appointment_id,))
    return cur.fetchone()

def _archive_booking(cur, appointment_id):
    cur.execute('CREATE TABLE IF NOT EXISTS cancelled_appointments AS SELECT * FROM appointments WHERE 0')
    cur.execute('INSERT INTO cancelled_appointments SELECT * FROM appointments WHERE id = ?', (appointment_id,))

def cancel_appointment_and_refund_deposit(appointment_id: int, db_path: str='clinic.db') -> dict:
    with closing(sqlite3.connect(db_path)) as conn:
        with conn:
            cur = conn.cursor()
            row = _load_booking(cur, appointment_id)
            if row is None:
                return {'ok': False, 'error': 'appointment not found'}
            _, status, charge_id, cents = row
            if status == 'completed':
                return {'ok': False, 'error': 'cannot cancel a completed appointment'}
            refund_id = None
            if charge_id and cents:
                refund = stripe.Refund.create(charge=charge_id, amount=cents, idempotency_key=f'cancel-appt-{appointment_id}')
                refund_id = refund['id']
            cur.execute('DELETE FROM reminders WHERE appointment_id = ?', (appointment_id,))
            _archive_booking(cur, appointment_id)
            cur.execute('DELETE FROM appointments WHERE id = ?', (appointment_id,))
    return {'ok': True, 'appointment_id': appointment_id, 'refund_id': refund_id, 'refunded_cents': cents or 0}
